#pragma once
#include "CoreMinimal.h"
#include "Components/StaticMeshComponent.h"
#include "Materials/MaterialInstanceDynamic.h"
#include "Materials/Material.h"
#include "GameFramework/Actor.h"

// Uses only engine primitives and a material generated by Tools/Bootstrap.py.
inline UStaticMeshComponent* ValleyMesh(AActor* Owner, USceneComponent* Parent,
    const TCHAR* Shape, FVector Position, FVector Size, FLinearColor Color, bool Solid = false)
{
    auto* Mesh = NewObject<UStaticMeshComponent>(Owner);
    Owner->AddInstanceComponent(Mesh);
    Mesh->SetupAttachment(Parent);
    Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr, *FString::Printf(TEXT("/Engine/BasicShapes/%s.%s"), Shape, Shape)));
    Mesh->SetRelativeLocation(Position);
    Mesh->SetRelativeScale3D(Size / 100.f);
    Mesh->SetCollisionEnabled(Solid ? ECollisionEnabled::QueryAndPhysics : ECollisionEnabled::NoCollision);
    Mesh->SetCollisionResponseToAllChannels(ECR_Block);
    if (auto* Base = LoadObject<UMaterialInterface>(nullptr, TEXT("/Game/Art/M_Prototype.M_Prototype")))
    {
        auto* Material = UMaterialInstanceDynamic::Create(Base, Owner);
        Material->SetVectorParameterValue(TEXT("Tint"), Color);
        Mesh->SetMaterial(0, Material);
    }
    Mesh->RegisterComponent();
    return Mesh;
}
